declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];if(!in_array($role,['admin','director','sub_director','headteacher'],true)){http_response_code(403);exit('Only school leadership can manage SMS templates.');}$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$ids=array_map('intval',array_column($schools,'id'));$school=(int)($_GET['school_id']??$ids[0]);if(!in_array($school,$ids,true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $item)if((int)$item['id']===$school)$schoolName=$item['name'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SMS templates · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/api.js"></script><script defer src="assets/app.js"></script><script defer src="assets/notification-settings.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">School settings <span>/</span> SMS notifications</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content" data-sms-settings data-api="api/school_sms_templates.php" data-school="<?=$school?>" data-csrf="<?=e(csrf_token())?>"><section class="welcome-row"><div><div class="eyebrow">SCHOOL COMMUNICATION</div><h1>SMS notification templates</h1><p class="muted"><?=e($schoolName)?> · Customize general wording for future alerts. Keep messages brief and avoid personal, academic, attendance, or fee details.</p></div><?php if(count($schools)>1):?><form method="get"><label for="sms-school">School</label><select id="sms-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $item):?><option value="<?=$item['id']?>"<?=(int)$item['id']===$school?' selected':''?>><?=e($item['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><div class="notice" data-sms-status role="status" aria-live="polite" hidden></div><div class="question-list" data-sms-template-list><p class="muted">Loading notification templates…</p></div><section class="content-section"><div class="section-heading"><div><div class="eyebrow">DELIVERY RECORDS</div><h2>Recent SMS activity</h2><p class="muted">Recipient phone numbers and message contents are hidden. Delivery states depend on provider reports.</p></div></div><div class="table-wrap"><table><thead><tr><th>Queued</th><th>Event</th><th>Queue state</th><th>Provider state</th><th>Attempts</th><th>Latest issue</th></tr></thead><tbody data-sms-delivery-list><tr><td colspan="6">Loading delivery activity…</td></tr></tbody></table></div><div class="planning-actions"><button type="button" class="button" data-sms-prev disabled>Previous</button><span class="muted" data-sms-page>Page 1</span><button type="button" class="button" data-sms-next disabled>Next</button></div></section><footer class="page-footer">ShuleLite · Notifications</footer></div></main></div></body></html>
